/**
 * emit to subscription queries of type FindReturnRequest,
 * but only if the id matches
 *
 * @param		entity	ReturnRequest
 */
	protected void emitFindReturnRequest( ReturnRequest entity ) {
		LOGGER.info("handling emitFindReturnRequest" );
		
	    queryUpdateEmitter.emit(FindReturnRequestQuery.class,
	                            query -> query.getFilter().getReturnRequestId().equals(entity.getReturnRequestId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllReturnRequest
	 * 
	 * @param		entity	ReturnRequest
	 */
	protected void emitFindAllReturnRequest( ReturnRequest entity ) {
		LOGGER.info("handling emitFindAllReturnRequest" );
		
	    queryUpdateEmitter.emit(FindAllReturnRequestQuery.class,
	                            query -> true,
	                            entity);
	}

